package com.atomosremote.nativeapp.audio

/**
 * R26.98/R26.99 - reconstructed LOCAL constructor argument images from the
 * official ATOMOS macOS x86_64 executable. THESE ARE NOT PROVEN ON-WIRE SCHEMAS.
 *
 * No SET is available here. All generated bytes remain operator-triggered
 * READ-NAMED GET candidates and never become calibrated numeric readbacks.
 */
object AudioR2698MacGetAbi {
    const val MACOS_EXECUTABLE_SHA256 = "b0e40f8da52e85abea159709f0045c270addbabb6456b7408f8c1ee6826e2d5e"

    data class Candidate(val key: String, val method: String, val opcode: Int,
                         val body: ByteArray, val provenance: String)

    private fun i32Le(v: Int): ByteArray = byteArrayOf(
        v.toByte(), (v ushr 8).toByte(), (v ushr 16).toByte(), (v ushr 24).toByte())

    /**
     * x86_64 0x10007CA00 GainGet argument image: Int32 index, zero byte,
     * Boolean flag. Index->Left/Right remains a candidate until validated.
     */
    fun forKey(key: String): Candidate? = when (key) {
        "gainLeft" -> Candidate(key, "GainGet", 0x06B7,
            i32Le(0) + byteArrayOf(0, 1), "macOS-local-ABI-six-byte-CANDIDATE")
        "gainRight" -> Candidate(key, "GainGet", 0x06B7,
            i32Le(1) + byteArrayOf(0, 1), "macOS-local-ABI-six-byte-CANDIDATE")
        // x86_64 0x10007CC40 uses helper 0x100088970 which constructs
        // a 4-byte int + zero byte before passing it to a generic encoder.
        "delay" -> Candidate(key, "FrameDelayGet", 0x06BA,
            i32Le(0) + byteArrayOf(0), "macOS-local-ABI-five-byte-CANDIDATE")
        // x86_64 0x10007C890 uses helper 0x100088160, passing a byte-sized
        // argument, unlike Android's previous empty-body candidate.
        "inputLevel" -> Candidate(key, "InputSourceGet", 0x06B4,
            byteArrayOf(0), "macOS-local-ABI-one-byte-CANDIDATE")
        else -> null
    }

    /**
     * R27.00 protocol gate. The 2026-10-17 AG2 trials returned 0xFFFF for
     * the local-ABI images. Constructor stack images are not protobuf bytes.
     * No GET-named candidate may be transmitted until its exact SwiftProtobuf
     * serialized request (including field tags) is independently proved.
     */
    fun canTransmitGet(@Suppress("UNUSED_PARAMETER") key: String): Boolean = false

    /** No numeric readback or SET schema has been hardware verified. */
    fun hardwareNumericValueVerified(@Suppress("UNUSED_PARAMETER") key: String) = false
    fun hardwareSetEnabled(@Suppress("UNUSED_PARAMETER") key: String) = false
}
